package httpapi

import (
	"bytes"
	"compress/gzip"
	"crypto/sha256"
	_ "embed"
	"encoding/hex"
	"io"
	"net/http"
	"strings"
	"sync"
)

// The OpenAPI description of the v1 REST API (OpenSpec change
// openapi-description): generated by TestOpenAPIDescription into
// docs/openapi.json and, compressed, into openapi.json.gz, which the server
// embeds and serves at GET /api/v1/openapi.json with its own version.

//go:embed openapi.json.gz
var openAPIEmbedded []byte

// openAPIMaxBytes bounds the decompressed description (it is about 1.2 MB).
const openAPIMaxBytes = 16 << 20

// openAPIServed is the description with this server's version, compressed,
// and its ETag; built once.
type openAPIServed struct {
	once sync.Once
	gz   []byte
	etag string
	err  error
}

func (o *openAPIServed) build(version string) {
	o.once.Do(func() {
		zr, err := gzip.NewReader(bytes.NewReader(openAPIEmbedded))
		if err != nil {
			o.err = err
			return
		}
		raw, err := io.ReadAll(io.LimitReader(zr, openAPIMaxBytes))
		if err != nil {
			o.err = err
			return
		}
		if version == "" {
			version = "dev"
		}
		raw = bytes.Replace(raw, []byte(`"version": "0.0.0-dev"`), []byte(`"version": "`+strings.ReplaceAll(version, `"`, "")+`"`), 1)
		var buf bytes.Buffer
		zw, _ := gzip.NewWriterLevel(&buf, gzip.BestCompression)
		_, _ = zw.Write(raw)
		_ = zw.Close()
		o.gz = buf.Bytes()
		sum := sha256.Sum256(o.gz)
		o.etag = `"` + hex.EncodeToString(sum[:8]) + `"`
	})
}

// handleOpenAPI answers the description: gzip when the client accepts it,
// 304 for a matching ETag, cacheable for an hour.
func (s *Server) handleOpenAPI(w http.ResponseWriter, r *http.Request) {
	s.openAPI.build(s.version)
	if s.openAPI.err != nil {
		writeError(w, http.StatusInternalServerError, "internal", "the API description could not be read")
		return
	}
	h := w.Header()
	h.Set("Cache-Control", "public, max-age=3600")
	h.Set("ETag", s.openAPI.etag)
	h.Set("Vary", "Accept-Encoding")
	h.Set("Access-Control-Allow-Origin", "*")
	if match := r.Header.Get("If-None-Match"); match != "" && strings.Contains(match, s.openAPI.etag) {
		w.WriteHeader(http.StatusNotModified)
		return
	}
	h.Set("Content-Type", "application/json; charset=utf-8")
	if strings.Contains(r.Header.Get("Accept-Encoding"), "gzip") {
		h.Set("Content-Encoding", "gzip")
		_, _ = w.Write(s.openAPI.gz)
		return
	}
	zr, err := gzip.NewReader(bytes.NewReader(s.openAPI.gz))
	if err != nil {
		writeError(w, http.StatusInternalServerError, "internal", "the API description could not be read")
		return
	}
	_, _ = io.Copy(w, io.LimitReader(zr, openAPIMaxBytes))
}
